      "市集、印刷术与允许异族登台的演出许可": "市集、印刷術與允許異族登臺的演出許可",
      "血斧角斗场": "血斧角鬥場",
      "裁判最好离远点，我的胜利通常会溅到前三排": "裁判最好離遠點，我的勝利通常會濺到前三排",
      "晶辉学院": "晶輝學院",
      "用晶体测量魔力，让法术可以被复现": "用晶體測量魔力，讓法術可以被複現",
