      "护林法、共享牧道与边地自治议会": "護林法、共享牧道與邊地自治議會",
      "机巧侏儒": "機巧侏儒",
      "专利制度、公开船坞与事故追责": "專利制度、公開船塢與事故追責",
      "虚空观测站": "虛空觀測站",
      "用长期观测区分天启、幻觉和噪声": "用長期觀測區分天啟、幻覺和噪聲",
      "黄金狮鹫族": "黃金獅鷲族",
      "空骑军籍、兽族居住权与救援航线": "空騎軍籍、獸族居住權與救援航線",
      "我加入王国不是为了变成人类，而是因为这里允许我保留自己，也允许我凭本事向前。": "我加入王國不是為了變成人類，而是因為這裡允許我保留自己，也允許我憑本事向前。",
      "血统只决定出生，制度和选择才决定我们能否并肩站在这里。": "血統只決定出生，制度和選擇才決定我們能否並肩站在這裡。",
      "今天我代表的不是归顺，而是一个异族也能公开竞争、堂堂正正赢得掌声的王国。": "今天我代表的不是歸順，而是一個異族也能公開競爭、堂堂正正贏得掌聲的王國。",
      "漂亮。能把我逼到这里，说明王都接纳的也确实是一位值得尊敬的对手。": "漂亮。能把我逼到這裡，說明王都接納的也確實是一位值得尊敬的對手。",
      "我不会替那些偏见证明异族只配躲在荒野。来，最后一轮！": "我不會替那些偏見證明異族只配躲在荒野。來，最後一輪！",
      "你赢了。愿这座竞技场继续证明：人类与异族可以争胜，却不必彼此仇恨。": "你贏了。願這座競技場繼續證明：人類與異族可以爭勝，卻不必彼此仇恨。",
      "出牌再快一点。观众买票不是来看你思考人生的。": "出牌再快一點。觀眾買票不是來看你思考人生的。",
      "你管这叫战线？我家的晾衣绳都比它更难突破。": "你管這叫戰線？我家的晾衣繩都比它更難突破。",
      "放心，我会给你留点体面——至少等裁判宣布以后再笑。": "放心，我會給你留點體面——至少等裁判宣佈以後再笑。",
      "别看记分牌了，它不会因为你盯得够久就站到你那边。": "別看記分牌了，它不會因為你盯得夠久就站到你那邊。",
      "刚才那一下还算像样。不过想让我闭嘴，你还差最后一段路。": "剛才那一下還算像樣。不過想讓我閉嘴，你還差最後一段路。",
      "别急着向观众挥手！我只是把翻盘留到最吵的时候。": "別急著向觀眾揮手！我只是把翻盤留到最吵的時候。",
      "今天算你赢。下次我会先击败你，再投诉这块明显偏向你的地板。": "今天算你贏。下次我會先擊敗你，再投訴這塊明顯偏向你的地板。",
      "别介意，我正在记录你的出牌习惯。真正危险的数据，往往来自自信的人。": "別介意，我正在記錄你的出牌習慣。真正危險的資料，往往來自自信的人。",
      "每次交换都在缩小答案范围。再过几轮，你的选择就会只剩一种。": "每次交換都在縮小答案範圍。再過幾輪，你的選擇就會只剩一種。",
      "竞技场比实验室诚实：错误的理论会当场掉血。": "競技場比實驗室誠實：錯誤的理論會當場掉血。",
      "放心，若你击败我，我会如实把结论写进报告。": "放心，若你擊敗我，我會如實把結論寫進報告。",
      "数据偏离预测了。很好，没有意外的研究才最无聊。": "資料偏離預測了。很好，沒有意外的研究才最無聊。",
      "样本正在反过来验证研究者……我承认这个结果很有说服力。": "樣本正在反過來驗證研究者……我承認這個結果很有說服力。",
      "结论成立：你的临场判断胜过我的模型。下一版论文会写上这一条。": "結論成立：你的臨場判斷勝過我的模型。下一版論文會寫上這一條。",
      "竞技场没有真正的仇敌，只有愿意把本领摆到阳光下的人。": "競技場沒有真正的仇敵，只有願意把本領擺到陽光下的人。",
      "别为保存生命而放弃阵线。荣誉来自承担风险，不是躲过风险。": "別為儲存生命而放棄陣線。榮譽來自承擔風險，不是躲過風險。",
      "观众记得胜负，战士应当记得自己在压力下做过什么选择。": "觀眾記得勝負，戰士應當記得自己在壓力下做過什麼選擇。",
      "无需留手。尊重对手最好的方式，就是拿出真正想赢的力量。": "無需留手。尊重對手最好的方式，就是拿出真正想贏的力量。",
      "好一记正面突破。疼痛会过去，失去判断才是真正的败势。": "好一記正面突破。疼痛會過去，失去判斷才是真正的敗勢。",
      "只剩最后一点生命，正好用来检验最后一点意志。": "只剩最後一點生命，正好用來檢驗最後一點意志。",
      "胜负已定。我记住了你的战术，也会把掌声留给配得上它的人。": "勝負已定。我記住了你的戰術，也會把掌聲留給配得上它的人。",
      "并": "並",
