      "四位魅魔军官拒绝撤离，以20点攻击力立即展开反击；小队将被杀退，但第五关仍会按通关结算。": "四位魅魔軍官拒絕撤離，以20點攻擊力立即展開反擊；小隊將被殺退，但第五關仍會按通關結算。",
      "四位魅魔军官没有进攻，只维持结界，为同伴撤离争取两回合。": "四位魅魔軍官沒有進攻，只維持結界，為同伴撤離爭取兩回合。",
      "千枝城反击开始：四名魅魔军官依次以20点攻击杀向小队。": "千枝城反擊開始：四名魅魔軍官依次以20點攻擊殺向小隊。",
      "四名军官的攻势击穿战线，魔族联军先遣队随即越过裂隙接管废墟；小队被迫撤出千枝城。": "四名軍官的攻勢擊穿戰線，魔族聯軍先遣隊隨即越過裂隙接管廢墟；小隊被迫撤出千枝城。",
