      "击穿战线": "擊穿戰線",
      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "第五關位於翡翠城南方的古城廢墟。灰狼與其他野獸憑藉速度和突襲擴張領地，最終迎戰銀灰狼女獵手。",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "第四關擁有二十個史萊姆首領節點。她們生命厚重、攻擊較低並會不斷再生；沿發光溪流深入森林，最終面對碧露大賢者·涅芙莉。",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "第三關擁有二十個熊族首領節點與一處農舍。沿農田支路調查被佔領的村莊，最終面對豐穗戰母·布蕾婭。",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "第二關擁有二十個首領節點。沿著哥布林軍團的防線一路推進，最終迎戰擁有200生命的翠影女王。",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "在四條前後排戰線上部署軍隊，撕開一路缺口，穿越十三個迷霧森林節點。每一次勝利，都會化為下一次遠征的力量。",
