      "灰狼和其他野兽速度极快，许多单位登场即可攻击。击败全部节点后，魔族联军会在废墟建立据点，之后可以反复挑战强大的军官与魔族军队。": "灰狼和其他野獸速度極快，許多單位登場即可攻擊。擊敗全部節點後，魔族聯軍會在廢墟建立據點，之後可以反覆挑戰強大的軍官與魔族軍隊。",
      "沿发光溪流与林间小径推进。每个史莱姆首领都会治疗自身与随从；击败节点后开启所有相邻路线，首胜卡牌会在战后揭晓。": "沿發光溪流與林間小徑推進。每個史萊姆首領都會治療自身與隨從；擊敗節點後開啟所有相鄰路線，首勝卡牌會在戰後揭曉。",
      "沿金色路线推进。击败节点后会开启所有相邻路线；抵达农舍旁的节点后，可与留守的农民夫妇交谈。每个首领的首胜奖励会在战后揭晓。": "沿金色路線推進。擊敗節點後會開啟所有相鄰路線；抵達農舍旁的節點後，可與留守的農民夫婦交談。每個首領的首勝獎勵會在戰後揭曉。",
      "击败任一节点即可开启相邻路线；翠影女王会在抵达右上方终点后开放。大部分节点由哥布林军团驻守。": "擊敗任一節點即可開啟相鄰路線；翠影女王會在抵達右上方終點後開放。大部分節點由哥布林軍團駐守。",
      "金边节点由更强的敌人驻守；首次击败会获得未知战利品。击败节点后仍可回到岔路挑战相邻路线。": "金邊節點由更強的敵人駐守；首次擊敗會獲得未知戰利品。擊敗節點後仍可回到岔路挑戰相鄰路線。",
      "击败一个节点后，所有相邻的未完成节点都会解锁。战败不会清空本关进度，切换关卡也会分别保存。": "擊敗一個節點後，所有相鄰的未完成節點都會解鎖。戰敗不會清空本關進度，切換關卡也會分別儲存。",
