      "你击退了不可一世的魔族驻军，获得500金币。她们仍会继续重建千枝城，之后仍可再次挑战。": "你擊退了不可一世的魔族駐軍，獲得500金幣。她們仍會繼續重建千枝城，之後仍可再次挑戰。",
