      "你击败银灰狼女猎手后，五位魅魔军官没有继续退避。她们救下狼族首领，以20点攻击的力量击溃小队，并决定在千枝城废墟建立魔族据点、重建这座千年前的共居之城。第五关奖励照常结算，英雄等级上限提升至25级；废墟地图上已经开放可反复挑战的魔族驻军。": "你擊敗銀灰狼女獵手後，五位魅魔軍官沒有繼續退避。她們救下狼族首領，以20點攻擊的力量擊潰小隊，並決定在千枝城廢墟建立魔族據點、重建這座千年前的共居之城。第五關獎勵照常結算，英雄等級上限提升至25級；廢墟地圖上已經開放可反覆挑戰的魔族駐軍。",
      "你击败了碧露大贤者·涅芙莉，迫使史莱姆族群退回森林深处，并将英雄等级上限提升至20级。": "你擊敗了碧露大賢者·涅芙莉，迫使史萊姆族群退回森林深處，並將英雄等級上限提升至20級。",
      "你击败了丰穗战母·布蕾娅，完成第三关并解锁东部梦幻森林与英雄20级上限。": "你擊敗了豐穗戰母·布蕾婭，完成第三關並解鎖東部夢幻森林與英雄20級上限。",
      "你击败了翠影女王，完成第二关的二十场首领战，并解锁王城南部的金麦农场与英雄15级上限。": "你擊敗了翠影女王，完成第二關的二十場首領戰，並解鎖王城南部的金麥農場與英雄15級上限。",
